import json

with open('BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    flow = json.load(f)

nodes = {n['id']: n for n in flow['nodes']}
edges = flow['edges']

print('=== NODES ===')
for nid, n in nodes.items():
    print(f'  {nid} ({n[\"type\"]})')

print()
print('=== EDGES ===')
for e in edges:
    print(f'  {e[\"sourceNodeId\"]}:{e[\"sourcePort\"]} -> {e[\"targetNodeId\"]}:{e[\"targetPort\"]}  [{e[\"id\"]}]')

print()
print('=== VALIDATION ===')
errors = []

# Check all edge references are valid node IDs
for e in edges:
    if e['sourceNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: sourceNodeId {e[\"sourceNodeId\"]} not found')
    if e['targetNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: targetNodeId {e[\"targetNodeId\"]} not found')

# Check exactly one start node
starts = [n for n in nodes.values() if n['type'] == 'core.trigger.manual']
print(f'Start nodes: {len(starts)} (expected 1)')
if len(starts) != 1:
    errors.append('Expected exactly 1 start node')

# Check exactly one end node
ends = [n for n in nodes.values() if n['type'] == 'core.control.end']
print(f'End nodes: {len(ends)} (expected 1)')
if len(ends) != 1:
    errors.append('Expected exactly 1 end node')

# Check decision node exists
decisions = [n for n in nodes.values() if n['type'] == 'core.logic.decision']
print(f'Decision nodes: {len(decisions)} (expected 1)')

# Check decision comes right after HTTP call
http_node = next((n for n in nodes.values() if n['type'] == 'core.action.http'), None)
decision_node = next((n for n in nodes.values() if n['type'] == 'core.logic.decision'), None)
if http_node and decision_node:
    http_to_decision = [e for e in edges if e['sourceNodeId'] == http_node['id'] and e['targetNodeId'] == decision_node['id']]
    print(f'HTTP -> Decision edge: {len(http_to_decision) > 0}')
    if not http_to_decision:
        errors.append('No direct edge from HTTP node to decision node')

# Check both branches go to formatSummary
format_node = next((n for n in nodes.values() if n['id'] == 'formatSummary'), None)
if decision_node and format_node:
    true_to_format = [e for e in edges if e['sourceNodeId'] == decision_node['id'] and e['sourcePort'] == 'true' and e['targetNodeId'] == format_node['id']]
    false_to_format = [e for e in edges if e['sourceNodeId'] == decision_node['id'] and e['sourcePort'] == 'false' and e['targetNodeId'] == format_node['id']]
    print(f'Decision true -> formatSummary: {len(true_to_format) > 0}')
    print(f'Decision false -> formatSummary: {len(false_to_format) > 0}')
    if not true_to_format:
        errors.append('No true branch from decision to formatSummary')
    if not false_to_format:
        errors.append('No false branch from decision to formatSummary')

# Check formatSummary -> end
end_node = next((n for n in nodes.values() if n['type'] == 'core.control.end'), None)
if format_node and end_node:
    format_to_end = [e for e in edges if e['sourceNodeId'] == format_node['id'] and e['targetNodeId'] == end_node['id']]
    print(f'formatSummary -> end: {len(format_to_end) > 0}')
    if not format_to_end:
        errors.append('No edge from formatSummary to end')

# Check decision expression references getWeather (not formatSummary)
if decision_node:
    expr = decision_node['inputs']['expression']
    print(f'Decision expression: {expr}')
    if 'getWeather' in expr:
        print('Decision expression references getWeather: OK')
    else:
        errors.append('Decision expression does not reference getWeather')
    if 'formatSummary' in expr:
        errors.append('Decision expression still references formatSummary (should reference getWeather)')

# Check formatSummary script uses matchedCaseId
if format_node:
    script = format_node['inputs']['script']
    print(f'formatSummary references matchedCaseId: {\"matchedCaseId\" in script}')
    if 'matchedCaseId' not in script:
        errors.append('formatSummary script does not reference checkTemperature.matchedCaseId')
    if 'nice day' in script:
        print('formatSummary has nice day message: OK')
    else:
        errors.append('formatSummary missing nice day message')
    if 'bring a jacket' in script:
        print('formatSummary has bring a jacket message: OK')
    else:
        errors.append('formatSummary missing bring a jacket message')

print()
if errors:
    print('ERRORS:')
    for err in errors:
        print(f'  ERROR: {err}')
else:
    print('All validations PASSED')
"

